-- Permission vocabulary and system roles of the corporate module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the corporate permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('currency:create'::text, 'currency'::text, 'create'::text, 'Create currency'::text),
            ('currency:delete'::text, 'currency'::text, 'delete'::text, 'Delete currency'::text),
            ('currency:purge'::text, 'currency'::text, 'purge'::text, 'Purge currency'::text),
            ('currency:read'::text, 'currency'::text, 'read'::text, 'Read currency'::text),
            ('currency:restore'::text, 'currency'::text, 'restore'::text, 'Restore currency'::text),
            ('currency:update'::text, 'currency'::text, 'update'::text, 'Update currency'::text),
            ('currency_exchange:create'::text, 'currency_exchange'::text, 'create'::text, 'Create currency exchange'::text),
            ('currency_exchange:delete'::text, 'currency_exchange'::text, 'delete'::text, 'Delete currency exchange'::text),
            ('currency_exchange:purge'::text, 'currency_exchange'::text, 'purge'::text, 'Purge currency exchange'::text),
            ('currency_exchange:read'::text, 'currency_exchange'::text, 'read'::text, 'Read currency exchange'::text),
            ('currency_exchange:restore'::text, 'currency_exchange'::text, 'restore'::text, 'Restore currency exchange'::text),
            ('currency_exchange:update'::text, 'currency_exchange'::text, 'update'::text, 'Update currency exchange'::text),
            ('incoterm:create'::text, 'incoterm'::text, 'create'::text, 'Create incoterm'::text),
            ('incoterm:delete'::text, 'incoterm'::text, 'delete'::text, 'Delete incoterm'::text),
            ('incoterm:purge'::text, 'incoterm'::text, 'purge'::text, 'Purge incoterm'::text),
            ('incoterm:read'::text, 'incoterm'::text, 'read'::text, 'Read incoterm'::text),
            ('incoterm:restore'::text, 'incoterm'::text, 'restore'::text, 'Restore incoterm'::text),
            ('incoterm:update'::text, 'incoterm'::text, 'update'::text, 'Update incoterm'::text),
            ('terms_and_conditions:create'::text, 'terms_and_conditions'::text, 'create'::text, 'Create terms and conditions'::text),
            ('terms_and_conditions:delete'::text, 'terms_and_conditions'::text, 'delete'::text, 'Delete terms and conditions'::text),
            ('terms_and_conditions:purge'::text, 'terms_and_conditions'::text, 'purge'::text, 'Purge terms and conditions'::text),
            ('terms_and_conditions:read'::text, 'terms_and_conditions'::text, 'read'::text, 'Read terms and conditions'::text),
            ('terms_and_conditions:restore'::text, 'terms_and_conditions'::text, 'restore'::text, 'Restore terms and conditions'::text),
            ('terms_and_conditions:update'::text, 'terms_and_conditions'::text, 'update'::text, 'Update terms and conditions'::text),
            ('territory:create'::text, 'territory'::text, 'create'::text, 'Create territory'::text),
            ('territory:delete'::text, 'territory'::text, 'delete'::text, 'Delete territory'::text),
            ('territory:purge'::text, 'territory'::text, 'purge'::text, 'Purge territory'::text),
            ('territory:read'::text, 'territory'::text, 'read'::text, 'Read territory'::text),
            ('territory:restore'::text, 'territory'::text, 'restore'::text, 'Restore territory'::text),
            ('territory:update'::text, 'territory'::text, 'update'::text, 'Update territory'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('currency:create'::text, 'currency'::text, 'create'::text, 'Create currency'::text),
            ('currency:delete'::text, 'currency'::text, 'delete'::text, 'Delete currency'::text),
            ('currency:purge'::text, 'currency'::text, 'purge'::text, 'Purge currency'::text),
            ('currency:read'::text, 'currency'::text, 'read'::text, 'Read currency'::text),
            ('currency:restore'::text, 'currency'::text, 'restore'::text, 'Restore currency'::text),
            ('currency:update'::text, 'currency'::text, 'update'::text, 'Update currency'::text),
            ('currency_exchange:create'::text, 'currency_exchange'::text, 'create'::text, 'Create currency exchange'::text),
            ('currency_exchange:delete'::text, 'currency_exchange'::text, 'delete'::text, 'Delete currency exchange'::text),
            ('currency_exchange:purge'::text, 'currency_exchange'::text, 'purge'::text, 'Purge currency exchange'::text),
            ('currency_exchange:read'::text, 'currency_exchange'::text, 'read'::text, 'Read currency exchange'::text),
            ('currency_exchange:restore'::text, 'currency_exchange'::text, 'restore'::text, 'Restore currency exchange'::text),
            ('currency_exchange:update'::text, 'currency_exchange'::text, 'update'::text, 'Update currency exchange'::text),
            ('incoterm:create'::text, 'incoterm'::text, 'create'::text, 'Create incoterm'::text),
            ('incoterm:delete'::text, 'incoterm'::text, 'delete'::text, 'Delete incoterm'::text),
            ('incoterm:purge'::text, 'incoterm'::text, 'purge'::text, 'Purge incoterm'::text),
            ('incoterm:read'::text, 'incoterm'::text, 'read'::text, 'Read incoterm'::text),
            ('incoterm:restore'::text, 'incoterm'::text, 'restore'::text, 'Restore incoterm'::text),
            ('incoterm:update'::text, 'incoterm'::text, 'update'::text, 'Update incoterm'::text),
            ('terms_and_conditions:create'::text, 'terms_and_conditions'::text, 'create'::text, 'Create terms and conditions'::text),
            ('terms_and_conditions:delete'::text, 'terms_and_conditions'::text, 'delete'::text, 'Delete terms and conditions'::text),
            ('terms_and_conditions:purge'::text, 'terms_and_conditions'::text, 'purge'::text, 'Purge terms and conditions'::text),
            ('terms_and_conditions:read'::text, 'terms_and_conditions'::text, 'read'::text, 'Read terms and conditions'::text),
            ('terms_and_conditions:restore'::text, 'terms_and_conditions'::text, 'restore'::text, 'Restore terms and conditions'::text),
            ('terms_and_conditions:update'::text, 'terms_and_conditions'::text, 'update'::text, 'Update terms and conditions'::text),
            ('territory:create'::text, 'territory'::text, 'create'::text, 'Create territory'::text),
            ('territory:delete'::text, 'territory'::text, 'delete'::text, 'Delete territory'::text),
            ('territory:purge'::text, 'territory'::text, 'purge'::text, 'Purge territory'::text),
            ('territory:read'::text, 'territory'::text, 'read'::text, 'Read territory'::text),
            ('territory:restore'::text, 'territory'::text, 'restore'::text, 'Restore territory'::text),
            ('territory:update'::text, 'territory'::text, 'update'::text, 'Update territory'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
